1	/****************************************************************************
2	 * Contest 2026 team 135 - hello app sample
3	 *
4	 * P2-A Route A: open the RPMsg control device (/dev/rpmsg/ap) and issue
5	 * RPMSG_CREATE_EPT_IOCTL to create an endpoint with an arbitrary service
6	 * name. The driver calls rpmsg_create_ept(name, src=ANY, dst=ANY), which
7	 * sends a Name Service announce to the remote (HPMCU) core automatically
8	 * and creates /dev/rpmsg-<name> on both sides. No payload is exchanged
9	 * here; the endpoint persists, held by the driver. This is the minimal
10	 * "NS announce only" probe for board-side bring-up.
11	 ****************************************************************************/
12	
13	#include <nuttx/config.h>
14	
15	#include <stdio.h>
16	#include <string.h>
17	#include <errno.h>
18	#include <fcntl.h>
19	#include <sys/ioctl.h>
20	
21	#include <nuttx/rpmsg/rpmsg.h>
22	
23	#ifdef CONFIG_RPMSG_CHAR
24	
25	/* Announce one RPMsg service so the remote core learns our endpoint.
26	 *
27	 * /dev/rpmsg/<cpuname> is the ioctl-only control device; it accepts
28	 * RPMSG_CREATE_EPT_IOCTL with a struct rpmsg_endpoint_info describing
29	 * the service to announce.
30	 */
31	
32	static int rpmsg_announce_demo(void)
33	{
34	  struct rpmsg_endpoint_info info;
35	  int fd;
36	  int ret;
37	
38	  fd = open("/dev/rpmsg/ap", O_RDWR);
39	  if (fd < 0)
40	    {
41	      printf("hello_app: open /dev/rpmsg/ap failed: %d (%s)\n",
42	             errno, strerror(errno));
43	      return -1;
44	    }
45	
46	  printf("hello_app: opened /dev/rpmsg/ap (fd=%d)\n", fd);
47	
48	  memset(&info, 0, sizeof(info));
49	  strlcpy(info.name, "rpmsg-demo", sizeof(info.name));
50	  info.src = RPMSG_ADDR_ANY;
51	  info.dst = RPMSG_ADDR_ANY;
52	
53	  ret = ioctl(fd, RPMSG_CREATE_EPT_IOCTL, (unsigned long)&info);
54	  if (ret < 0)
55	    {
56	      printf("hello_app: RPMSG_CREATE_EPT_IOCTL failed: %d (%s)\n",
57	             errno, strerror(errno));
58	      close(fd);
59	      return -1;
60	    }
61	
62	  printf("hello_app: announced RPMsg channel \"%s\""
63	         " (expect /dev/rpmsg-rpmsg-demo)\n", info.name);
64	
65	  /* Endpoint is now held by the driver; the control fd can be closed. */
66	
67	  close(fd);
68	  return 0;
69	}
70	
71	#endif /* CONFIG_RPMSG_CHAR */
72	
73	int main(int argc, char *argv[])
74	{
75	  int ret = 0;
76	
77	  printf("Hello from openvela contest 2026 team 135!\n");
78	
79	#ifdef CONFIG_RPMSG_CHAR
80	  ret = rpmsg_announce_demo();
81	#else
82	  printf("hello_app: CONFIG_RPMSG_CHAR not enabled, skip RPMsg announce\n");
83	#endif
84	
85	  return ret;
86	}
