58	static void rpmsg_char_usage(const char *progname)
59	{
60	  printf("Usage: %s [-t <type>] [-c <ctrl>] [-n <name>] [-s <src>] "
61	         "[-d <dst>]\n"
62	         "  type: the test type, now we support: echo, destroy\n"
63	         "  ctrl: the rpmsg ctrl char device name, e.g, /dev/rpmsg/ap\n"
64	         "  name: the rpmsg char device name you want to create, will\n"
65	         "        append \"rpmsg-raw-\" or \"rpmsg-\", e.g, if set\n"
66	         "        to \"test\", the rpmsg char device name will be\n"
67	         "        /dev/rpmsgX (Linux) or /dev/rpmsg-test (NuttX)\n"
68	         "  src : the rpmsg char device source address, default is ANY\n"
69	         "  dst : the rpmsg char device destination address, default is\n"
70	         "        ANY\n",
71	         progname);
72	}
73	
74	static int rpmsg_char_arg_prase(struct rpmsg_char_arg_s *args,
75	                                int argc, char *argv[])
76	{
77	  int opt;
78	
79	  /* Set the default value */
80	
81	  memset(args, 0, sizeof(*args));
82	  args->src  = RPMSG_ADDR_ANY;
83	  args->dst  = RPMSG_ADDR_ANY;
84	  args->type = "echo";
85	
86	  while ((opt = getopt(argc, argv, "h:t:c:n:s:d")) != -1)
87	    {
88	      switch (opt)
89	        {
90	          case 'h':
91	            rpmsg_char_usage(argv[0]);
92	            return 0;
93	          case 't':
94	            args->type = optarg;
95	            break;
96	          case 'c':
97	            args->ctrl = optarg;
98	            break;
99	          case 'n':
100	            args->name = optarg;
101	            break;
102	          case 's':
103	            args->src = strtoul(optarg, NULL, 0);
104	            break;
105	          case 'd':
106	            args->dst = strtoul(optarg, NULL, 0);
107	            break;
108	          default:
109	            printf("ERROR: arguments are error, print usage:\n");
110	            rpmsg_char_usage(argv[0]);
111	            return ERROR;
112	        }
113	    }
114	
115	  if (!((args->src == RPMSG_ADDR_ANY && args->dst == RPMSG_ADDR_ANY) ||
116	        (args->src != RPMSG_ADDR_ANY && args->dst != RPMSG_ADDR_ANY)))
117	    {
118	      printf("Invalid src:0x%" PRIx32 " dst:0x%" PRIx32 " name: %s\n",
119	             args->src, args->dst, args->name);
120	      return ERROR;
121	    }
122	
123	  return 0;
124	}
