  else /* args->src != RPMSG_ADDR_ANY && args->dst != RPMSG_ADDR_ANY */
    {
      ret = ioctl(fd, RPMSG_DESTROY_EPT_IOCTL, 0);
    }

  assert(ret >= 0);
  close(fd);
